var r=[{title:`Mekanik över huvudet`,text:`Börja från en stabil stående eller sittande bas. Håll revbenen ungefär staplade över bäckenet, spänn bålen och pressa uppåt längs en bekväm bana så att armarna slutar över huvudet utan en stor lutning bakåt. Dina skulderblad roterar normalt uppåt när armarna höjs, och att försöka hålla fast dem under hela lyftet kan stå i vägen för det.`},{title:`Rörlighet och individuella skillnader`,text:`Att nå över huvudet kräver tillräcklig axelrörelse och oftast lite hjälp från övre ryggen. Axelns anatomi och bekväma greppvinklar skiljer sig från person till person. Om en press med rak stång är obekväm kan en hantelpress med neutralt grepp, en landminepress eller ett kortare omfång över huvudet passa dig bättre. Skarp smärta betyder stopp, så försök inte stretcha genom den.`},{title:`Kroppsviktsalternativ`,text:`En pike push-up placerar höfterna högt, så att dina axlar hanterar mer av belastningen. En pike push-up med höjda fötter kan vara svårare och kräver mer balans och utrymme. För nybörjare är en lätt stående hantelpress ofta enklare och lättare att justera än en svår kroppsviktsvariant.`},{title:`Vanliga teknikproblem`,text:`En stor svank i ländryggen, att pressa vikten långt framför dig och att jäkta skakiga repetitioner betyder oftast att belastningen är för tung eller din kontroll är begränsad. Sänk vikten, öva banan och håll benen utanför en strikt press. En push press är en separat övning som medvetet lägger till bendrivning.`},{title:`Så använder du TrainUp`,text:`Din plan tar bara med övningar över huvudet när din utrustning och takhöjden i din Profil lämnar tillräckligt med utrymme. Den anpassar också övningarna efter din koordination. Om känsliga axlar eller belastning genom ryggraden gör vanliga pressar över huvudet till ett dåligt val, lägg till en begränsning för det kroppsområdet i Profil så väljer planen mindre krävande alternativ.`}];var n=[{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: teknik vid styrketräning (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: grunder i säkerhet och styrketräning`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};